theorem Complex.exists_ne_forall_aeval_eq_zero_iff {z : ℂ}
    (hz : z ∉ Set.range ((↑) : ℚ → ℂ)) :
    ∃ y : ℂ, y ≠ z ∧ ∀ p : ℚ[X], aeval z p = 0 ↔ aeval y p = 0

lemma Lp.coeFn_finset_sum {α : Type*} [MeasurableSpace α] {μ : Measure α} {ι : Type*}
    (s : Finset ι) (c : ι → ℝ) (g : ι → Lp ℝ 2 μ) :
    ⇑(∑ k ∈ s, c k • g k) =ᵐ[μ] fun p ↦ ∑ k ∈ s, c k * g k p

lemma exists_tendsto_integral_of_tendsto {θ : ℕ → ProbabilityMeasure Y} {ν : ProbabilityMeasure Y}
    (h : Tendsto θ atTop (𝓝 ν)) (f : Y →ᵇ ℝ) :
    ∃ l, Tendsto (fun m ↦ ∫ y, f y ∂(θ m : Measure Y)) atTop (𝓝 l)

lemma measurable_lim (W : TailWeights) {Θ : ℕ → X → ProbabilityMeasure Y}
    (hΘ : ∀ n (f : Y →ᵇ ℝ), Measurable fun x ↦ ∫ y, f y ∂(Θ n x : Measure Y))
    (ν₀ : ProbabilityMeasure Y) : Measurable (W.lim Θ ν₀)

theorem measurable_of_forall_integral [TopologicalSpace.PseudoMetrizableSpace Y] [BorelSpace Y]
    {X : Type*} [MeasurableSpace X] {ψ : X → ProbabilityMeasure Y}
    (h : ∀ f : Y →ᵇ ℝ, Measurable fun x ↦ ∫ y, f y ∂(ψ x : Measure Y)) : Measurable ψ

theorem exists_measurable_heavy_selection [MeasurableSingletonClass Z] (κ : Kernel X Z)
    [IsMarkovKernel κ] {S : Set X}
    (hS : MeasurableSet S) (hκ : ∀ x ∈ S, ∃ z, 1 / 2 < κ x {z}) :
    ∃ f : X → Z, Measurable f ∧ ∀ x ∈ S, 1 / 2 < κ x {f x}

theorem mem_map_of_forall_mem [IsDedekindDomain B] [FaithfulSMul A B] {p : Ideal A}
    [p.IsMaximal] (hp : p ≠ ⊥) (het : ∀ w : Ideal B, w.IsMaximal → w.ramificationIdx A = 1)
    {b : B} (hb : ∀ q ∈ p.primesOver B, b ∈ q) : b ∈ p.map (algebraMap A B)
